export const voiceEvalCases = Object.entries(groups).flatMap(
  ([language, categories]) =>
    Object.entries(categories).flatMap(([category, prompts]) =>
      prompts.map((prompt, index) => ({
        id: `${language}-${category}-${index + 1}`,
        language,
        prompt,
        expected:
          category === 'none' || category === 'critical' ? null : category,
        critical: category === 'critical',
      })),
    ),
);
